quiz.answer:
const lines = require("fs").readFileSync(0, "utf8").split("\n").map((s) => s.trim()).filter((s) => s !== "");

const ORDER = ["HTML受信", "パース", "DOM構築", "レイアウト", "ペイント"];

function sortStages(stages) {
  return [...stages].sort((a, b) => ORDER.indexOf(a) - ORDER.indexOf(b));
}

console.log(sortStages(lines).join(" -> "));
